<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>CSMS | RCHSEMS · PT Kereta Api Indonesia</title><link rel="stylesheet" href="/assets/portal.css?v={{ filemtime(public_path('assets/portal.css')) }}"></head><body>
<div class="boot-screen" id="bootScreen" role="status" aria-live="polite"><div class="boot-card"><img id="bootLogo" class="boot-logo" alt="Logo KAI"><div class="boot-spinner" aria-hidden="true"></div><strong>CSMS</strong><small>RCHSEMS</small><span id="bootMessage">Memuat aplikasi...</span></div></div>
<div class="login-overlay" id="authScreen" style="display:none"><div class="lang-switch lang-switch-floating" role="group" aria-label="Bahasa"><button type="button" data-lang="id" class="selected" aria-pressed="true" title="Bahasa Indonesia">ID</button><button type="button" data-lang="en" aria-pressed="false" title="English">EN</button></div><div class="login-box">
<div class="brand" style="border:0;padding:0;color:#102b55"><img class="brand-logo" src="data:image/png;base64," alt="Logo KAI"><div><strong>CSMS</strong><small style="color:#64748b">RCHSEMS · Portal Kontraktor & Keselamatan</small></div></div>
<h1 id="authTitle">Masuk ke aplikasi</h1><p id="authDesc">Gunakan akun sesuai peran Anda.</p>
<div id="authTabs" class="login-tabs segmented" role="tablist"><button id="tabLogin" class="selected" type="button" role="tab" aria-selected="true" data-click="showAuth" data-args='["login"]'>Login</button><button id="tabRegister" type="button" role="tab" aria-selected="false" data-click="showAuth" data-args='["register"]'>Pendaftaran Akun</button></div>
<form id="authForm" novalidate><div id="fieldUser" class="field"><input id="authUser" name="username" type="email" autocomplete="username" required placeholder=" "><label for="authUser">Akun / Email</label><p class="field-hint">Gunakan email resmi perusahaan atau unit Anda.</p></div>
<div id="fieldPass" class="field mt-3"><div class="password-field"><input id="authPass" name="password" type="password" autocomplete="current-password" required minlength="12" placeholder=" "><button id="authPasswordToggle" class="password-toggle" type="button" aria-label="Tampilkan password" aria-controls="authPass" aria-pressed="false" data-click="toggleAuthPassword"><span id="authPasswordIcon" class="msym" aria-hidden="true">visibility</span></button></div><label for="authPass">Password</label><p class="field-hint">Minimal 12 karakter.</p></div>
<div id="fieldCode" class="field mt-3 hide"><input id="authCode" name="code" type="text" autocomplete="one-time-code" maxlength="16" placeholder=" "><label for="authCode">Kode autentikasi</label><p class="field-hint">Masukkan 6 digit dari aplikasi autentikator, atau satu kode pemulihan.</p></div>
<div id="fieldNewPass" class="field mt-3 hide"><input id="authNewPass" name="new_password" type="password" autocomplete="new-password" minlength="12" maxlength="128" placeholder=" "><label for="authNewPass">Password baru (minimal 12 karakter)</label></div>
<div class="auth-links"><button id="linkForgot" class="btn btn-text btn-sm" type="button" data-click="showAuth" data-args='["forgot"]'>Lupa password?</button><button id="linkBack" class="btn btn-text btn-sm hide" type="button" data-click="showAuth" data-args='["login"]'>Kembali ke login</button></div>
<div id="registerFields" class="hide"><div class="field mt-3"><input id="authName" name="name" placeholder=" " autocomplete="name"><label for="authName">Nama lengkap</label></div>
<div class="field mt-3"><label class="field-label" for="authRoleOptions">Peran akun (centang semua yang sesuai)</label><div id="authRoleOptions" class="role-options"><label class="role-option"><input type="checkbox" name="authRole" value="vendor" checked> <span>Vendor</span></label></div><div class="role-help">Pendaftaran mandiri hanya untuk akun Vendor. Akun Verifikator, Validator, Bagian Pengadaan, dan Admin harus disiapkan oleh administrator sistem.</div></div>
<p class="note note-info mt-4"><span>Akun internal (Verifikator, Validator, Pengadaan, dan Admin) tidak dapat dibuat melalui pendaftaran mandiri. Gunakan akun internal yang disiapkan administrator.</span></p></div>
<div id="authError" class="login-error" role="alert" aria-live="polite"></div><button class="btn btn-filled"  id="authSubmit" type="submit" style="width:100%;margin-top:16px"><span id="authSubmitText">Masuk</span></button></form>
<div class="footer">Akun internal disiapkan oleh administrator sistem.</div></div></div>
<div class="app">
<aside class="side"><div class="brand"><img class="logo" src="data:image/png;base64," alt="Logo KAI"><div class="brand-text"><strong>CSMS</strong><small>RCHSEMS Portal</small></div></div>
<nav class="nav" id="nav" aria-label="Navigasi utama">
<button class="active" data-page="dashboard" aria-current="page"><span class="msym nav-icon" aria-hidden="true">dashboard</span><span>Dashboard</span></button>
<button data-page="vendors"><span class="msym nav-icon" aria-hidden="true">apartment</span><span>Data Vendor</span></button>
<button data-page="register"><span class="msym nav-icon" aria-hidden="true">add_circle</span><span>Pendaftaran Vendor</span></button>
<button data-page="questionnaire"><span class="msym nav-icon" aria-hidden="true">assignment</span><span>Pra-Kualifikasi</span></button>
<button data-page="verification"><span class="msym nav-icon" aria-hidden="true">search</span><span>Verifikasi Dokumen</span></button>
<button data-page="validation"><span class="msym nav-icon" aria-hidden="true">task_alt</span><span>Validasi Lapangan</span></button>
<button data-page="risk"><span class="msym nav-icon" aria-hidden="true">bar_chart</span><span>Hasil &amp; Lingkup Risiko</span></button>
<button data-page="accounts"><span class="msym nav-icon" aria-hidden="true">person</span><span>Kelola Akun Internal</span></button>
<button id="navMore" class="nav-more" type="button" aria-haspopup="dialog"><span class="msym nav-icon" aria-hidden="true">more_horiz</span><span>Lainnya</span></button>
</nav><div class="sidefoot">

<p class="sidefoot-note">PT Kereta Api Indonesia (Persero)<br>Semakin Melayani</p>
</div></aside>
<main class="main"><header class="top"><div class="top-title-group"><strong class="top-title" id="topTitle">Contractor Safety Management System &middot; RCHSEMS</strong></div><div class="top-actions"><div class="lang-switch" role="group" aria-label="Bahasa"><button type="button" data-lang="id" class="selected" aria-pressed="true" title="Bahasa Indonesia">ID</button><button type="button" data-lang="en" aria-pressed="false" title="English">EN</button></div><button type="button" class="top-avatar" id="accountBtn" data-click="openAccountSheet" aria-haspopup="menu" aria-label="Akun Anda" title="Akun Anda"><span id="accountAvatar">?</span></button></div></header>
<div class="content" id="view"></div></main></div>
<script src="/assets/qr.js?v={{ filemtime(public_path('assets/qr.js')) }}" defer></script>
<script src="/assets/i18n.js?v={{ filemtime(public_path('assets/i18n.js')) }}" defer></script>
<script src="/assets/portal.js?v={{ filemtime(public_path('assets/portal.js')) }}" defer></script></body></html>
